import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<Long, Long> cacheMap = new HashMap<>();

    static long countDigitsInLong(long x) {
        long cnt = 0;
        while (x != 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }

    static long reverseLongNumber(long x) {
        long[] digits = new long[17];
        int pos = 0;
        long absX = Math.abs(x);
        while (absX != 0) {
            digits[pos++] = absX % 10;
            absX /= 10;
        }
        long res = 0;
        for (int i = pos - 1; i >= 0; i--) {
            res = res * 10 + digits[i];
        }
        return x < 0 ? -res : res;
    }

    static long previousLongValue(long x) {
        long c = 0;
        long absX = Math.abs(x);
        while (absX != 0) {
            c *= 10;
            c += (x < 0 ? -1 : 1);
            absX /= 10;
        }
        c = c * 10 + 1;
        return x - c;
    }

    static long getLastDigit(long x) {
        while (x >= 10 || x <= -10) {
            x /= 10;
        }
        return x;
    }

    static long deleteLeadingDigits(long x) {
        long[] digits = new long[17];
        int p = 0;
        long absX = Math.abs(x);
        while (absX >= 10) {
            digits[p++] = absX % 10;
            absX /= 10;
        }
        long res = 0;
        for (int i = p - 1; i >= 0; i--) {
            res = res * 10 + digits[i];
        }
        return x < 0 ? -res : res;
    }

    static long computeResult(long x) {
        if (x <= 11) {
            return Math.min(13 - x, x);
        }
        if (cacheMap.containsKey(x))
            return cacheMap.get(x);
        long n = 0, t = 1;
        while (t < x) {
            t = t * 10 + 1;
            n++;
        }
        if (x * 2 >= t) {
            long res1 = computeResult(t - x) + n + 1;
            long res2 = (x / (t / 10)) * n + computeResult(x % (t / 10));
            long result = Math.min(res1, res2);
            cacheMap.put(x, result);
            return result;
        } else {
            long result = (x / (t / 10)) * n + computeResult(x % (t / 10));
            cacheMap.put(x, result);
            return result;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long a = scanner.nextLong();
        System.out.println(computeResult(a));
        scanner.close();
    }
}
